return {api_version=1,id="EX1_578",name="Savagery",text="Deal damage equal to your hero's Attack to a minion.",set="EXPERT1",type="spell",class="druid",rarity="rare",cost=1,target_mode="required",targets=function(ctx)return ctx:minions()end,on_play=function(ctx,self,target)local p=ctx:controller(self);cardlib.effects.damage(ctx, target,ctx:entity(ctx:player(p).hero).attack)end}
